        # fallback to global ops
        import builtins
        ops = builtins.__dict__.get('ops', None)
    if ops is None:
        # Fallback: define minimal ops
        class DummyOps:
            @staticmethod
            def relu(x): return (x > 0).to(x.dtype) * x
            @staticmethod
            def sub(a, b): return a - b
            @staticmethod
            def mul(a, b): return a * b
            @staticmethod
            def mean(x): return x.mean()
            @staticmethod
            def ones_like(x): return x.new_ones(x.shape)
        ops = DummyOps()
    if weight is None:
        weight = ops.ones_like(log_prob_w)
    # Clamp weight to >= 0 for stability
